export function holeLevel(votes){const progress=Math.max(0,Math.min(25,votes));return {radius:1.075+progress*.0476,capacity:votes>=18?3:votes>=12?2:1}}
export function standings(counts,parties,selected){const sorted=parties.slice().sort((a,b)=>counts[b]-counts[a]);const top=counts[sorted[0]]||0,leaders=sorted.filter(p=>counts[p]===top),rival=sorted.find(p=>p!==selected);const threat=rival&&(counts[rival]>=20||counts[rival]>counts[selected])?rival:null;return {sorted,leader:leaders.length===1?leaders[0]:null,threat,urgent:!!threat&&counts[threat]>=20}}
export function nearestSupporter(people,party,position){let best=null,distance=Infinity;for(const p of people){if(p.party!==party||!p.voted||p.loyal||p.state!=='walk'||p.cool>0)continue;const d=(p.g.position.x-position.x)**2+(p.g.position.z-position.z)**2;if(d<distance){distance=d;best=p}}return best}
export function canHuntHole(big,small,now){return big!==small&&big.mode==='active'&&small.mode==='active'&&now>=big.shieldUntil&&now>=small.shieldUntil&&big.radius>=small.radius*1.15}
export function canSwallowHole(big,small,now){return canHuntHole(big,small,now)&&Math.hypot(big.g.position.x-small.g.position.x,big.g.position.z-small.g.position.z)<big.radius-small.radius*.3}
